#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'tarrant-clarity-november': 'https://results.enr.clarityelections.com/TX/Tarrant/127297/', 'tarrant-civix-results': 'https://goelect.txelections.civixapps.com/ivis-enr-ui/races', 'tarrant-november-download': 'https://www.tarrantcountytx.gov/content/dam/main/elections/2026/1126/reports/ENR_1126.zip', 'krgv-elections': 'https://www.krgv.com/elections', 'khou-midterms-guide': 'https://www.khou.com/article/news/politics/elections/texas-midterm-november-3-2026-guide/285-13ef75f2-bddc-4cb4-a50a-95ccda5c510e', 'wfaa-midterms-guide': 'https://www.wfaa.com/article/news/local/vote/voter-guide-everything-you-need-to-know-about-nov-3-midterm-election-north-texas/287-b757295f-5868-4dd5-aa55-af360c49d5de', 'sos-dates': 'https://www.sos.state.tx.us/elections/voter/important-election-dates.shtml', 'sos-2026-calendar': 'https://www.sos.state.tx.us/elections/laws/advisory2026-21-november-3-election-law-calendar.shtml', 'tarrant-november': 'https://www.tarrantcountytx.gov/en/elections/past-election-information/2026-archives/november-3--2026--joint-general-and-special-election-results.html', 'tribune-primary': 'https://apps.texastribune.org/features/2026/primary-election-results-2026/', 'ksat-statewide-primary': 'https://www.ksat.com/vote-2026/2026/03/03/election-results-2026-texas-statewide-races-democrat-and-republican-primaries/', 'kvia-results': 'https://kvia.com/full-election-results/', 'kcbd-results': 'https://www.kcbd.com/politics/election-results/', 'wfaa-home': 'https://www.wfaa.com/', 'khou-home': 'https://www.khou.com/', 'krgv-home': 'https://www.krgv.com/', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'kltv-results': 'https://www.kltv.com/politics/election-results/', 'kltv-state-panel': 'https://www.kltv.com/texas-election-results/', 'kfda-results': 'https://www.newschannel10.com/politics/election-results/', 'kfda-runoff': 'https://www.newschannel10.com/2026/05/27/see-may-2026-joint-primary-election-runoff-results-here/', 'kristv-home': 'https://www.kristv.com/', 'kxan-home': 'https://www.kxan.com/', 'kltv-ap-national': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/110246/32468.html', 'kltv-ap-state': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/110246/32544.html', 'kristv-local-results': 'https://www.kristv.com/news/general-election/city-county-election-results', 'kristv-primary-blog': 'https://www.kristv.com/news/local-news/local-elections/election-day-blog', 'kristv-close-runoff': 'https://www.kristv.com/news/local-news/in-your-neighborhood/corpus-christi/northwest-side/too-close-to-call-city-council-district-1-runoff-election-results-still-in-the-air', 'kristv-nueces-vendor': 'https://results.enr.clarityelections.com/TX/Nueces/116160/web.307039/', 'kristv-local-elections': 'https://www.kristv.com/news/local-news/local-elections', 'sos-history-index': 'https://www.sos.state.tx.us/elections/historical/index.shtml', 'sos-historical-results': 'https://elections.sos.state.tx.us/index.htm', 'sos-results-app': 'https://results.texas-election.com/races', 'sos-results-archive': 'https://www.sos.state.tx.us/elections/historical/elections-results-archive.shtml', 'sos-turnout-controls': 'https://www.sos.state.tx.us/elections/historical/70-92.shtml', 'sos-registration-index': 'https://www.sos.state.tx.us/elections/historical/vrfig.shtml', 'tlc-precincts-index': 'https://data.capitol.texas.gov/dataset/precincts', 'tlc-vtd-index': 'https://data.capitol.texas.gov/dataset/vtds', 'tlc-election-about': 'https://data.capitol.texas.gov/topic/about/elections', 'tlc-election-index': 'https://data.capitol.texas.gov/dataset?groups=elections', 'tlc-2024-general': 'https://data.capitol.texas.gov/dataset/2024_general', 'tlc-2022-general': 'https://data.capitol.texas.gov/dataset/2022_general', 'tlc-2024-senate-vtd': 'https://ted.capitol.texas.gov/api/Offices/510/2/vtd', 'tlc-2024-president-vtd': 'https://ted.capitol.texas.gov/api/Offices/510/1/vtd', 'tlc-2024-voterdata-vtd': 'https://ted.capitol.texas.gov/api/Offices/510/1428/vtd', 'tlc-2022-governor-vtd': 'https://ted.capitol.texas.gov/api/Offices/497/37/vtd', 'tlc-2022-voterdata-vtd': 'https://ted.capitol.texas.gov/api/Offices/497/1428/vtd', 'tribune-main-module': 'https://apps.texastribune.org/features/2026/primary-election-results-2026/scripts/main.abfab15ba1.mjs', 'tribune-vendor-module': 'https://apps.texastribune.org/features/2026/primary-election-results-2026/scripts/1.05739c36db.mjs', 'tribune-page-module': 'https://apps.texastribune.org/features/2026/primary-election-results-2026/scripts/3.94500f2a4f.mjs', 'tribune-primary-public-json': 'https://s3.amazonaws.com/sos-test-2.texastribune.org/2026_primary/republic_json/results_FLAT.json'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
